    @SuppressWarnings("serial")
    public static final class SessionException extends RuntimeException {
        public final String code;
        public final boolean retryable = false;
        public SessionException(String message, Throwable cause, boolean inDoubt) {
            super(message, cause); code = inDoubt ? "agent_session_in_doubt" : "agent_session_refused";
        }
    }
