    private static boolean digest(String value) { return value != null && value.length() == 64 && value.chars().allMatch(ch -> "0123456789abcdef".indexOf(ch) >= 0); }
    private static boolean equal(Object left, Object right) { return MessageDigest.isEqual(bytes(left), bytes(right)); }
    private static boolean flag(Map<String, Object> value, String key) { return Boolean.TRUE.equals(value.get(key)); }
    private static boolean count(String key) { return !key.equals("cost") && !key.equals("elapsed_seconds"); }
    private static double now() { return System.currentTimeMillis() / 1000d; }

    private static void validate(Object value, Map<String, Object> schema, Map<String, Object> schemas, int depth) {
        if (depth > 64 || schema.containsKey("unsupported")) throw refused("argument schema is not qualified");
        if (schema.containsKey("ref")) {
            String ref = string(schema.get("ref")), prefix = "#/components/schemas/";
            if (!ref.startsWith(prefix)) throw refused("unresolved schema reference");
            String segment = ref.substring(prefix.length());
            if (segment.isEmpty() || segment.contains("/")) throw refused("invalid schema reference");
            for (int i = 0; i < segment.length(); i++)
                if (segment.charAt(i) == '~' && (++i >= segment.length() || "01".indexOf(segment.charAt(i)) < 0)) throw refused("invalid schema reference escape");
            String name = segment.replace("~1", "/").replace("~0", "~");
            if (!schemas.containsKey(name)) throw refused("unresolved schema reference");
            validate(value, object(schemas.get(name)), schemas, depth + 1);
        }
        if (value == null && flag(schema, "nullable")) return;
        for (String keyword : List.of("one_of", "any_of", "all_of")) {
            if (!schema.containsKey(keyword)) continue;
            List<?> branches = array(schema.get(keyword)); int matches = 0;
            for (Object branch : branches) {
                try { validate(value, object(branch), schemas, depth + 1); matches++; }
                catch (SessionException mismatch) { continue; } // Whole graph was qualified by the generator.
            }
            if (keyword.equals("one_of") && matches != 1 || keyword.equals("any_of") && matches == 0 || keyword.equals("all_of") && matches != branches.size()) throw refused("schema composition mismatch");
        }
        if (schema.containsKey("not")) {
            boolean matches = true;
            try { validate(value, object(schema.get("not")), schemas, depth + 1); }
            catch (SessionException mismatch) { matches = false; }
            if (matches) throw refused("excluded schema");
        }
        if (schema.containsKey("const") && !equal(value, schema.get("const"))) throw refused("const mismatch");
        if (schema.containsKey("enum")) {
            List<?> values = array(schema.get("enum"));
            if (!values.isEmpty() && values.stream().noneMatch(item -> equal(item, value))) throw refused("enum mismatch");
        }
        if (schema.containsKey("type")) {
            boolean valid = switch (string(schema.get("type"))) {
                case "null" -> value == null;
                case "object" -> value instanceof Map<?, ?>;
                case "array" -> value instanceof List<?>;
                case "string" -> value instanceof String;
                case "boolean" -> value instanceof Boolean;
                case "number" -> value instanceof Number;
                case "integer" -> value instanceof Number && Math.rint(number(value)) == number(value);
                default -> false;
            };
            if (!valid) throw refused("argument type mismatch");
        }
        Map<String, Object> bounds = object(schema.getOrDefault("constraints", Map.of()));
        if (bounds.containsKey("pattern")) throw refused("regex-constrained arguments are not qualified");
        if (value instanceof Number) {
            double n = number(value); range(n, bounds, "minimum", "maximum");
            if (bounds.containsKey("exclusiveMinimum") && n <= number(bounds.get("exclusiveMinimum")) || bounds.containsKey("exclusiveMaximum") && n >= number(bounds.get("exclusiveMaximum"))) throw refused("exclusive numeric bound");
            if (bounds.containsKey("multipleOf")) {
                double divisor = number(bounds.get("multipleOf"));
                if (!(divisor > 0) || Math.abs(n / divisor - Math.rint(n / divisor)) > 1e-9) throw refused("multipleOf mismatch");
            }
        }
        if (value instanceof String text) range(text.codePointCount(0, text.length()), bounds, "minLength", "maxLength");
        if (value instanceof List<?> items) {
            range(items.size(), bounds, "minItems", "maxItems"); Set<String> unique = new HashSet<>();
            for (Object item : items) {
                if (flag(bounds, "uniqueItems") && !unique.add(Base64.getEncoder().encodeToString(bytes(item)))) throw refused("duplicate array item");
                if (schema.containsKey("items")) validate(item, object(schema.get("items")), schemas, depth + 1);
            }
        }
        if (value instanceof Map<?, ?>) {
            Map<String, Object> fields = object(value); range(fields.size(), bounds, "minProperties", "maxProperties");
            for (Object required : array(schema.getOrDefault("required", List.of())))
                if (!fields.containsKey(string(required))) throw refused("required property missing");
            Map<String, Object> properties = object(schema.getOrDefault("properties", Map.of()));
            for (Map.Entry<String, Object> item : fields.entrySet()) {
                if (properties.containsKey(item.getKey())) validate(item.getValue(), object(properties.get(item.getKey())), schemas, depth + 1);
                else if (Boolean.FALSE.equals(schema.get("additional_properties"))) throw refused("additional property forbidden");
                else if (schema.get("additional_properties") instanceof Map<?, ?>) validate(item.getValue(), object(schema.get("additional_properties")), schemas, depth + 1);
            }
        }
    }
    private static void range(double value, Map<String, Object> bounds, String min, String max) {
        if (bounds.containsKey(min) && value < number(bounds.get(min)) || bounds.containsKey(max) && value > number(bounds.get(max))) throw refused("argument constraint mismatch");
    }

    /** Local authenticated storage; keep the checkpoint, external key and permanent guard. */
    public static final class Checkpoint {
        private final Path path;
        private final byte[] key;
        private String revision = "";
        private static final int MAX_BYTES = 128 << 20;
        public Checkpoint(Path path, byte[] key) {
            if (path == null || key == null || key.length < 32) throw refused("checkpoint path and external key of at least 32 bytes required");
            this.path = path.toAbsolutePath().normalize(); this.key = key.clone();
        }
        private Path sibling(String suffix) { return path.resolveSibling(path.getFileName().toString() + suffix); }
        private byte[] mac(Object value) {
            try { Mac mac = Mac.getInstance("HmacSHA256"); mac.init(new SecretKeySpec(key, "HmacSHA256")); return mac.doFinal(bytes(value)); }
            catch (GeneralSecurityException error) { throw refused("checkpoint authentication unavailable", error); }
        }
        private byte[] read() throws IOException {
            try (FileChannel channel = FileChannel.open(path, StandardOpenOption.READ)) {
                long length = channel.size();
                if (length > MAX_BYTES) throw refused("checkpoint byte limit");
                ByteBuffer buffer = ByteBuffer.allocate((int) length);
                while (buffer.hasRemaining()) if (channel.read(buffer) < 0) throw refused("checkpoint changed during read");
                if (channel.read(ByteBuffer.allocate(1)) != -1) throw refused("checkpoint changed during read");
                return buffer.array();
            } catch (NoSuchFileException missing) { return null; }
        }
        private synchronized Map<String, Object> load() {
            try {
                byte[] payload = read();
                if (payload == null) {
                    if (Files.exists(sibling(".started"))) throw refused("checkpoint missing after initialization");
                    revision = ""; return null;
                }
                if (!Files.exists(sibling(".started"))) throw refused("checkpoint initialization guard missing");
                Map<String, Object> envelope = object(parse(payload));
                if (!envelope.keySet().equals(Set.of("state", "mac"))) throw refused("invalid checkpoint envelope");
                byte[] supplied;
                try { supplied = java.util.HexFormat.of().parseHex(string(envelope.get("mac"))); }
                catch (IllegalArgumentException error) { throw refused("checkpoint authentication failed", error); }
                if (!MessageDigest.isEqual(supplied, mac(envelope.get("state")))) throw refused("checkpoint authentication failed");
                revision = hash(payload); return object(envelope.get("state"));
            } catch (IOException error) { throw refused("checkpoint load failed", error); }
        }
        private synchronized void save(Map<String, Object> state) {
            try {
                Files.createDirectories(path.getParent());
                Path lock = sibling(".lock");
                FileChannel writer = FileChannel.open(lock, StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE);
                try (writer) {
                    Path temporary = null;
                    try {
                        if (!writer.isOpen()) throw refused("checkpoint writer unavailable");
                        byte[] previous = read();
                        if (!(previous == null ? "" : hash(previous)).equals(revision)) throw refused("checkpoint changed by another session");
                        byte[] payload = bytes(map("state", state, "mac", hex(mac(state))));
                        if (payload.length > MAX_BYTES) throw refused("checkpoint byte limit");
                        if (revision.isEmpty()) {
                            try (FileChannel guard = FileChannel.open(sibling(".started"), StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE)) {
                                ByteBuffer data = ByteBuffer.wrap(PROTOCOL.getBytes(StandardCharsets.UTF_8));
                                while (data.hasRemaining()) guard.write(data); guard.force(true);
                            }
                        } else if (!Files.exists(sibling(".started"))) throw refused("checkpoint initialization guard missing");
                        temporary = sibling("." + UUID.randomUUID() + ".tmp");
                        try (FileChannel file = FileChannel.open(temporary, StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE)) {
                            ByteBuffer data = ByteBuffer.wrap(payload);
                            while (data.hasRemaining()) file.write(data); file.force(true);
                        }
                        Files.move(temporary, path, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
                        temporary = null; revision = hash(payload);
                    } finally { if (temporary != null) Files.deleteIfExists(temporary); }
                } finally { Files.delete(lock); } // Acquisition completed before entering this try.
            } catch (IOException error) { throw refused("checkpoint persistence failed", error); }
        }
    }

